// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadBangers = makeLoadFont('Bangers');

// Module-level font loading for robust Lambda / SSR rendering
const { fontFamily: bangersFamily } = loadBangers();

// Precise 24-point alternating patterns for hand-drawn comic style bursts
const whiteBurstPattern = [
  1.0, 0.35, 1.1, 0.3, 0.95, 0.4, 1.25, 0.3,
  1.0, 0.35, 1.15, 0.25, 0.85, 0.38, 1.3, 0.28,
  1.05, 0.32, 1.1, 0.35, 0.9, 0.4, 1.2, 0.3
];

const orangeBurstPattern = [
  1.15, 0.4, 1.25, 0.35, 1.05, 0.45, 1.4, 0.35,
  1.15, 0.4, 1.3, 0.3, 0.95, 0.45, 1.45, 0.33,
  1.2, 0.37, 1.25, 0.4, 1.0, 0.45, 1.35, 0.35
];

// Definition of dramatic radial kinetic sparks/shards
interface Shard {
  angle: number; // in degrees
  lengthMultiplier: number;
  distanceMultiplier: number;
  color: "white" | "orange";
  thickness: number;
}

const SHARDS: Shard[] = [
  // Top-left sector
  { angle: -140, lengthMultiplier: 1.5, distanceMultiplier: 1.2, color: "white", thickness: 4 },
  { angle: -160, lengthMultiplier: 1.2, distanceMultiplier: 1.1, color: "orange", thickness: 5 },
  // Top-right sector
  { angle: -60, lengthMultiplier: 1.6, distanceMultiplier: 1.3, color: "orange", thickness: 6 },
  { angle: -40, lengthMultiplier: 1.1, distanceMultiplier: 1.05, color: "white", thickness: 3 },
  // Right sector
  { angle: -10, lengthMultiplier: 1.4, distanceMultiplier: 1.25, color: "orange", thickness: 5 },
  { angle: 10, lengthMultiplier: 1.2, distanceMultiplier: 1.15, color: "white", thickness: 4 },
  // Bottom-right sector
  { angle: 45, lengthMultiplier: 1.5, distanceMultiplier: 1.2, color: "orange", thickness: 5 },
  { angle: 65, lengthMultiplier: 1.1, distanceMultiplier: 1.0, color: "white", thickness: 3 },
  // Bottom-left sector
  { angle: 120, lengthMultiplier: 1.3, distanceMultiplier: 1.15, color: "orange", thickness: 4 },
  { angle: 140, lengthMultiplier: 1.6, distanceMultiplier: 1.3, color: "white", thickness: 5 },
  // Top / bottom central vertical shards
  { angle: 80, lengthMultiplier: 1.4, distanceMultiplier: 1.1, color: "orange", thickness: 4 },
  { angle: -100, lengthMultiplier: 1.0, distanceMultiplier: 1.0, color: "white", thickness: 3 },
];



export type PowAnimationProps = Record<string, any>;

const PowAnimation: React.FC<PowAnimationProps> = ({
  backgroundColor = "#091122",
  transparentBackground = false,
  durationInSeconds = 5,
  text = "POW!",
  impactFrame = 10,
  scaleMultiplier = 1.0,
  textPrimaryColor = "#e23c24",
  textShadowColor = "#080d19",
  burstMainColor = "#faf8f2",
  burstAccentColor = "#d83a1c",
  shakeIntensity = 25,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Responsive sizing logic
  const baseScaleSize = Math.min(width, height) * 0.38;
  const fontSize = Math.min(width, height) * 0.24;

  // Render safety logic
  const resolvedBgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Generating a responsive solid 3D shadow style for retro print design
  const generate3DShadow = (color: string, depth: number) => {
    const shadows = [];
    for (let i = 1; i <= depth; i++) {
      shadows.push(`${i}px ${i}px 0px ${color}`);
    }
    return shadows.join(", ");
  };

  // Burst pop animation timing (pops out slightly before text impacts)
  const burstStartFrame = Math.max(0, impactFrame - 6);
  const burstSpring = spring({
    frame: frame - burstStartFrame,
    fps,
    config: { stiffness: 180, damping: 11, mass: 0.9 },
  });

  const burstScale = interpolate(burstSpring, [0, 1], [0, 1.0]) * scaleMultiplier;

  // Dynamic hand-drawn wiggle generator (perturbing points every frame for comic energy)
  const wiggleAmount = interpolate(frame, [0, 20], [0.02, 0.008], {
    extrapolateRight: "clamp",
  });

  const getBurstPointsString = (
    baseSize: number,
    pattern: number[],
    wiggleSeed: number,
    angleOffset: number = 0
  ) => {
    const points: string[] = [];
    const count = pattern.length;
    for (let i = 0; i < count; i++) {
      const angle = (i * 2 * Math.PI) / count + angleOffset;
      const wiggle = Math.sin(frame * 0.75 + i + wiggleSeed) * wiggleAmount;
      const currentRadius = (pattern[i] + wiggle) * baseSize;
      const x = Math.cos(angle) * currentRadius;
      const y = Math.sin(angle) * currentRadius;
      points.push(`${x},${y}`);
    }
    return points.join(" ");
  };

  const whiteBurstPoints = getBurstPointsString(baseScaleSize, whiteBurstPattern, 1, -0.05);
  const orangeBurstPoints = getBurstPointsString(baseScaleSize * 1.1, orangeBurstPattern, 2, 0.05);

  // Screen shake calculations triggered on impact
  const shakeDecay = interpolate(frame, [impactFrame, impactFrame + 25], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const shakeX = Math.sin(frame * 1.8) * shakeIntensity * shakeDecay;
  const shakeY = Math.cos(frame * 2.1) * shakeIntensity * shakeDecay;

  // Flash element on impact
  const flashOpacity = interpolate(
    frame,
    [impactFrame - 1, impactFrame, impactFrame + 4],
    [0, 0.8, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const containerStyle: React.CSSProperties = {
    backgroundColor: resolvedBgColor,
    backgroundImage: transparentBackground
      ? "none"
      : `radial-gradient(circle, rgba(255, 255, 255, 0.07) 0%, rgba(0, 0, 0, 0) 75%)`,
    width: "100%",
    height: "100%",
    overflow: "hidden",
  };

  const shakeStyle: React.CSSProperties = {
    transform: `translate(${shakeX}px, ${shakeY}px)`,
    width: "100%",
    height: "100%",
    position: "absolute",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    transition: "none",
  };

  const textLetters = text.split("");

  return (
    <AbsoluteFill style={containerStyle}>
      {/* Dynamic Screen Shaking Container */}
      <div style={shakeStyle}>
        
        {/* Central Vector Canvas (Bursts & Flying Needle Shards) */}
        <svg
          width={width}
          height={height}
          viewBox={`-${width / 2} -${height / 2} ${width} ${height}`}
          style={{
            position: "absolute",
            overflow: "visible",
            transform: `scale(${burstScale})`,
            transition: "none",
          }}
        >
          {/* 1. Background Shards */}
          {SHARDS.map((shard, idx) => {
            const shardStart = impactFrame + 2;
            const shardProgress = interpolate(frame - shardStart, [0, 20], [0, 1], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });

            if (frame < shardStart) return null;

            const easeProgress = Easing.out(Easing.quad)(shardProgress);
            const rad = (shard.angle * Math.PI) / 180;

            const startR = baseScaleSize * (0.35 + easeProgress * 0.9) * shard.distanceMultiplier;
            const endR = startR + (baseScaleSize * 0.22 * shard.lengthMultiplier * (1 - easeProgress));

            const x1 = Math.cos(rad) * startR;
            const y1 = Math.sin(rad) * startR;
            const x2 = Math.cos(rad) * endR;
            const y2 = Math.sin(rad) * endR;

            const color = shard.color === "white" ? burstMainColor : burstAccentColor;
            const opacity = interpolate(shardProgress, [0.7, 1], [1, 0], {
              extrapolateRight: "clamp",
            });

            return (
              <line
                key={idx}
                x1={x1}
                y1={y1}
                x2={x2}
                y2={y2}
                stroke={color}
                strokeWidth={shard.thickness}
                strokeLinecap="round"
                opacity={opacity}
              />
            );
          })}

          {/* 2. Layered Comic Bursts with offset hard solid shadows */}
          {/* Orange Burst Shadow */}
          <polygon
            points={orangeBurstPoints}
            fill={textShadowColor}
            transform="translate(14, 14)"
          />
          {/* Orange Burst Primary */}
          <polygon points={orangeBurstPoints} fill={burstAccentColor} />

          {/* White Burst Shadow */}
          <polygon
            points={whiteBurstPoints}
            fill={textShadowColor}
            transform="translate(10, 10)"
          />
          {/* White Burst Primary */}
          <polygon points={whiteBurstPoints} fill={burstMainColor} />
        </svg>

        {/* 3. Text Overlay (Staggered Dynamic Spring Entrance for each character) */}
        <div
          style={{
            position: "absolute",
            display: "flex",
            flexDirection: "row",
            justifyContent: "center",
            alignItems: "center",
            transform: "rotate(-5deg)",
            transition: "none",
          }}
        >
          {textLetters.map((char, idx) => {
            const letterStartFrame = impactFrame + idx * 2;
            
            const letterSpring = spring({
              frame: frame - letterStartFrame,
              fps,
              config: { stiffness: 220, damping: 9, mass: 0.8 },
            });

            // Calculate entrance scaling
            const scale = interpolate(letterSpring, [0, 1], [0, 1]);

            // Gentle idle text hover to keep composition feeling live/fluid
            const hoverOffset = Math.sin(frame * 0.12 + idx) * 6;
            const individualRotation = (idx - textLetters.length / 2) * 2 + Math.sin(frame * 0.15 + idx) * 3;

            return (
              <span
                key={idx}
                style={{
                  display: "inline-block",
                  fontFamily: bangersFamily,
                  fontSize,
                  lineHeight: 1,
                  color: textPrimaryColor,
                  textTransform: "uppercase",
                  margin: "0 2px",
                  textShadow: generate3DShadow(textShadowColor, 16),
                  transform: `scale(${scale}) rotate(${individualRotation}deg) translateY(${hoverOffset}px)`,
                  transition: "none",
                }}
              >
                {char}
              </span>
            );
          })}
        </div>
      </div>

      {/* Comic Impact Screen Flash Overlays */}
      <AbsoluteFill
        style={{
          backgroundColor: "#ffffff",
          opacity: flashOpacity,
          pointerEvents: "none",
          transition: "none",
        }}
      />
    </AbsoluteFill>
  );
};

export default PowAnimation;